mapper.select:
SELECT w.drafting_work_category_id, w.tenant_id, w.cata_type_code, w.code_name, w.category_item_id, CASE WHEN cg.group_code = 'WF_FORM_CATEGORY' THEN ci.item_nm END AS category_name, w.reg_term_id, CASE WHEN rg.group_code = 'WF_FORM_CYCLE' THEN ri.item_nm ELSE w.reg_term END AS reg_term, w.reviewer_id, COALESCE(ru.user_nm, '') AS reviewer_name, w.approver_id, COALESCE(au.user_nm, '') AS approver_name, CASE WHEN COALESCE(am.assignee_count, 0) = 0 THEN '' WHEN am.assignee_count = 1 THEN am.first_assignee_name ELSE am.first_assignee_name || ' 외 ' || CAST(am.assignee_count - 1 AS varchar) || '명' END AS assignee_summary, w.use_at, COALESCE(NULLIF(TRIM(cu.user_nm), ''), CAST(w.created_by AS varchar), '-') AS created_by_name, TO_CHAR(w.created_at, 'YYYY-MM-DD HH24:MI') AS created_at, ( w.drafting_work_template_json IS NOT NULL OR NULLIF(TRIM(COALESCE(w.drafting_work_template_html, '')), '') IS NOT NULL ) AS has_document FROM public.tb_drafting_work_category w LEFT JOIN public.tb_common_code_item ci ON ci.common_code_item_id = w.category_item_id AND ci.tenant_id = w.tenant_id LEFT JOIN public.tb_common_code_group cg ON cg.common_code_group_id = ci.group_id AND cg.tenant_id = w.tenant_id LEFT JOIN public.tb_common_code_item ri ON ri.common_code_item_id = w.reg_term_id AND ri.tenant_id = w.tenant_id LEFT JOIN public.tb_common_code_group rg ON rg.common_code_group_id = ri.group_id AND rg.tenant_id = w.tenant_id AND rg.group_code = 'WF_FORM_CYCLE' LEFT JOIN public.tb_user cu ON cu.tenant_id = w.tenant_id AND cu.login_id = w.created_by LEFT JOIN public.tb_user ru ON ru.tenant_id = w.tenant_id AND ru.login_id = w.reviewer_id LEFT JOIN public.tb_user au ON au.tenant_id = w.tenant_id AND au.login_id = w.approver_id LEFT JOIN LATERAL ( SELECT COUNT(*) AS assignee_count, (ARRAY_AGG(COALESCE(NULLIF(TRIM(u.user_nm), ''), a.employee_no) ORDER BY a.drafting_work_category_authority_id))[1] AS first_assignee_name FROM public.tb_drafting_work_category_authority a LEFT JOIN public.tb_user u ON u.tenant_id = a.tenant_id AND CAST(u.user_id AS varchar) = a.employee_no WHERE a.tenant_id = w.tenant_id AND a.drafting_work_category_id = w.drafting_work_category_id AND a.use_at = 'Y' AND COALESCE(a.delete_status, 'N') <> 'Y' ) am ON TRUE WHERE w.tenant_id = #{tenantId} AND COALESCE(w.delete_status, 'N') <> 'Y'
AND ( LOWER(COALESCE(w.cata_type_code, '')) LIKE LOWER(CONCAT('%', #{keyword}, '%')) OR LOWER(COALESCE(w.code_name, '')) LIKE LOWER(CONCAT('%', #{keyword}, '%')) )
AND w.category_item_id = #{categoryItemId}
AND w.drafting_work_category_id = #{workId}
AND w.reg_term_id = #{regTermId}
AND w.use_at = #{useAt}
ORDER BY w.view_seq ASC, w.drafting_work_category_id ASC

SELECT drafting_work_category_id
FROM public.tb_drafting_work_category
WHERE tenant_id = #{tenantId}
  AND drafting_work_category_id = #{workId}
  AND COALESCE(delete_status, 'N') <> 'Y'
FOR UPDATE

SELECT drafting_work_category_id
FROM public.tb_drafting_work_category
WHERE tenant_id = #{tenantId}
  AND cata_type_code = #{cataTypeCode}
  AND COALESCE(delete_status, 'N') <> 'Y'
LIMIT 1
